SELECT COUNT(1)
FROM medical_registration r
JOIN patient_user_info c ON r.patient_card_id = c.id
WHERE c.user_id = #{userId}
  AND STR_TO_DATE(r.create_time, '%Y-%m-%d') = #{today}

mapper.update:
UPDATE medical_registration
SET payment_status = 4
WHERE out_trade_no = #{outTradeNo} AND payment_status = 1;
